import{z as i,x as o,o as e,c as p,q as r,j as B,D as a,d as A,s as n,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"语音服务化：ASR 与 TTS","description":"","frontmatter":{"title":"语音服务化：ASR 与 TTS","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-speech-serving.md","filePath":"llm/mm-speech-serving.md","lastUpdated":1791063341000}'),D={name:"llm/mm-speech-serving.md"};function T(d,E,S,m,C,F){const t=o("Mermaid");return e(),p("div",null,[E[2]||(E[2]=r('<h1 id="语音服务化-asr-与-tts" tabindex="-1">语音服务化：ASR 与 TTS <a class="header-anchor" href="#语音服务化-asr-与-tts" aria-label="Permalink to &quot;语音服务化：ASR 与 TTS&quot;">​</a></h1><div class="epigraph"><p>对话体感的延迟预算是一秒：端点尾点、识别终局、首 token、第一段音频，四段相加，没有一段可以挥霍。</p><footer>—— 据 Radford et al., Whisper, 2023；Wang et al., VALL-E, 2023；Qwen3-ASR Technical Report 整理</footer></div><p><a href="/llm/mm-video-serving">上一课</a>把视频做成流式负载；语音从第一天起就是流式，且双向都要。级联（ASR–LLM–TTS）与端到端的系统切法已由<a href="/llm/e2e-speech-dialogue">端到端语音对话</a>对照过，本课写服务侧的账：流式 ASR 的分块与端点、TTS 的首音频、级联各段的延迟分账与打断处理。语音 tokenizer 与全双工栈只在需要处引用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>级联把一次对话切成三跳，每跳自带排队，总延迟是相加的：端点判定没等到话音结束就提前截断，等太久用户以为系统没听见；ASR 出终局结果前，LLM 无事可做；TTS 拿不到整句就开不了声。四段加起来轻松过秒，体感即「对讲机」而不是「对话」。更难的是流式 ASR 本身不是普通推理：识别要边到边出部分结果，<a href="/llm/qwen3-asr-vllm">Qwen3-ASR 的服务口径</a>明确流式只挂推理后端且不与批推理、时间戳同开——流式、批处理、时间戳三者的组合约束是工程事实，不是实现缺陷。</p><p><span class="marginnote">VAD（Voice Activity Detection，语音活动检测）就是「分辨此刻有没有人在说话」的小模型：不看内容，只管有声没声。别小看它——端点判定和打断触发都靠它，它一慢或误判，整条对话的节奏就乱了。</span></p><p>TTS 侧对应的问题是首音频：合成整句再播，句子越长首音频越迟；按 codec token 流式出声（<a href="/llm/valle-tts">VALL-E</a> 一类把语音当语言模型续写）延迟低，但音质与稳定性随流式粒度变化。两头夹住 LLM：它必须在句号处就可切句，而不是等完整段落。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>服务把对话延迟拆成四段 SLA 分账：<strong>端点段</strong>（VAD 判定话音结束）、<strong>识别段</strong>（从尾点到 ASR 终局）、<strong>生成段</strong>（LLM 首 token）、<strong>合成段</strong>（TTS 首音频）。每段独立监控、独立设预算，总账超限时知道砍谁。识别段靠部分结果压缩体感延迟：partial 流式上屏让用户边说边看，final 才交给 LLM——partial 允许回改，final 必须稳定，两层语义要分开暴露。</p><p>合成段按句切分：LLM 流式输出在句号或子句边界切句，TTS 对已完成句子立刻开合成，首音频延迟从「整段生成完」变成「首句生成完」；vocoder 按帧流式出样本，进一步压尾。<strong>打断</strong>是级联最脆的一环：用户插话时，播放立刻停、未播句子队列丢弃、LLM 生成作废、VAD 重新接管——四步要原子完成，漏掉「丢弃未播队列」就会把旧答案的后半句播给已经换了话题的用户。</p><p><span class="marginnote">漏掉「丢弃未播队列」会怎样？用户已改问「那北京呢」，系统却把上一条答案的后半句「……杭州西湖非常适合游玩」播了出来——这种答非所问比慢一秒糟糕得多，用户还会重复提问，负载反而更重。</span></p><p><span class="marginnote">典型级联拆账：端点尾点约 300 ms、ASR 终局约 200 ms、LLM 首 token 约 300 ms、TTS 首音频约 200 ms，合计约一秒。端点阈值每多加 100 ms，用户体感不是「慢了一点」，而是「它在等我说话」。</span></p>',12)),(e(),B(s,null,{default:a(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AUD%5B%22%E9%9F%B3%E9%A2%91%E6%B5%81%22%5D%20--%3E%20VAD%5B%22VAD%20%E5%88%86%E5%9D%97%E4%B8%8E%E7%AB%AF%E7%82%B9%22%5D%0A%20%20VAD%20--%3E%20ASR%5B%22%E6%B5%81%E5%BC%8F%20ASR%22%5D%0A%20%20ASR%20--%3E%20PAR%5B%22partial%20%E9%83%A8%E5%88%86%E7%BB%93%E6%9E%9C%E4%B8%8A%E5%B1%8F%22%5D%0A%20%20ASR%20--%3E%20FIN%5B%22final%20%E7%BB%88%E5%B1%80%E6%96%87%E6%9C%AC%22%5D%0A%20%20FIN%20--%3E%20LLM%5B%22LLM%20%E6%B5%81%E5%BC%8F%E7%94%9F%E6%88%90%22%5D%0A%20%20LLM%20--%3E%20CUT%7B%22%E5%8F%A5%E5%8F%B7%E8%BE%B9%E7%95%8C%3F%22%7D%0A%20%20CUT%20--%3E%7C%E6%98%AF%7C%20TTS%5B%22TTS%20%E5%90%88%E6%88%90%E8%AF%A5%E5%8F%A5%22%5D%0A%20%20CUT%20--%3E%7C%E5%90%A6%7C%20LLM%0A%20%20TTS%20--%3E%20PLAY%5B%22%E6%B5%81%E5%BC%8F%E6%92%AD%E6%94%BE%22%5D%0A%20%20PLAY%20--%3E%20BARGE%7B%22%E7%94%A8%E6%88%B7%E6%8F%92%E8%AF%9D%3F%22%7D%0A%20%20BARGE%20--%3E%7C%E6%98%AF%7C%20STOP%5B%22%E5%81%9C%E6%92%AD%E3%80%81%E5%BC%83%E9%98%9F%E3%80%81%E4%BD%9C%E5%BA%9F%E7%94%9F%E6%88%90%22%5D%0A%20%20STOP%20--%3E%20VAD%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[A("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"四段里重叠空间最大的是识别与合成之外的两处。LLM 首 token 不必等 TTS：生成流切句后逐句喂给合成队列，生成与播放流水化，总延迟趋近「端点 + 识别 + 首 token + 首句合成」而不是四段终局相加。端点判定是延迟与截断的直接旋钮：VAD 能量阈值加语义完整度（句子是否说完整）双条件判定，前者抓「说完了」，后者抓「还想说」；只有 VAD 的服务在用户换气时抢答，加语义条件又吃掉尾点预算——阈值要按场景调，客服与闲聊的合理值不同。",-1)),(e(),B(s,null,{default:a(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEG%5B%22%E7%94%A8%E6%88%B7%E5%81%9C%E9%A1%BF%22%5D%20--%3E%20E%7B%22%E8%83%BD%E9%87%8F%E6%9D%A1%E4%BB%B6%3A%20%E9%9D%99%E9%9F%B3%E8%B6%85%E6%97%B6%3F%22%7D%0A%20%20E%20--%3E%7C%E5%90%A6%7C%20CONT%5B%22%E6%9C%AA%E7%BB%93%E6%9D%9F%EF%BC%8C%E7%BB%A7%E7%BB%AD%E6%94%B6%E9%9F%B3%22%5D%0A%20%20E%20--%3E%7C%E6%98%AF%7C%20S%7B%22%E8%AF%AD%E4%B9%89%E6%9D%A1%E4%BB%B6%3A%20%E5%8F%A5%E5%AD%90%E5%AE%8C%E6%95%B4%3F%22%7D%0A%20%20S%20--%3E%7C%22%E5%AE%8C%E6%95%B4%22%7C%20CUT%5B%22%E5%87%BA%E7%AB%AF%E7%82%B9%EF%BC%8CASR%20%E5%87%BA%E7%BB%88%E5%B1%80%22%5D%0A%20%20S%20--%3E%7C%22%E5%8F%AA%E6%98%AF%E6%8D%A2%E6%B0%94%22%7C%20KEEP%5B%22%E4%B8%8D%E6%8A%A2%E7%AD%94%EF%BC%8C%E7%BB%A7%E7%BB%AD%E6%94%B6%E9%9F%B3%22%5D%0A%20%20CUT%20--%3E%20OK%5B%22%E4%BD%93%E6%84%9F%EF%BC%9A%E6%8E%A5%E4%BD%8F%E4%BA%86%E8%AF%9D%E8%BD%AE%22%5D%0A%20%20CONT%20--%3E%20RISK1%5B%22%E9%9D%99%E9%9F%B3%E9%98%88%E5%80%BC%E5%A4%AA%E9%95%BF%EF%BC%9A%E5%83%8F%E6%B2%A1%E5%90%AC%E8%A7%81%22%5D%0A%20%20KEEP%20--%3E%20RISK2%5B%22%E4%B8%8D%E8%AE%BE%E8%AF%AD%E4%B9%89%E6%9D%A1%E4%BB%B6%EF%BC%9A%E6%8D%A2%E6%B0%94%E8%A2%AB%E6%8A%A2%E7%AD%94%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p>识别段还有一个隐藏量：音频块长。编码器按帧窗吃音频，块越短延迟越低、上下文越少、准确率越掉；<a href="/llm/qwen3-asr-token-rate">token 速率</a>与块长的匹配决定流式识别的性价比。ASR 错误会沿级联传播且被放大：LLM 把误识别当真指令执行，错误在下游看起来像幻觉，根因却在识别——日志必须把三跳的中间产物（final 文本、LLM 输入）落盘，否则无法归因。</p><p><span class="marginnote">识别错误被放大成幻觉，可以类比传话游戏：第一个人把话听错，后面每个人（LLM）都一本正经地顺着错处编出通顺的话——越往后越离谱，且没人知道源头在哪。三跳中间产物落盘，才能把「模型胡说」按回「识别听错」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>端到端语音栈省掉跳数，首响应更快，但服务语义反而更难：没有文本中间产物，打断、审计、合规都失去抓手，全双工的轮次控制见<a href="/llm/full-duplex-speech">全双工语音</a>。TTS 读出的是文本的表面：逆文本归一化没做，日期、数字、单位会被逐字念错，这类错误在评测里像模型问题，在服务里是管线问题。多说话人与语种切换是另一个谱系（<a href="/llm/whisper-large-v3">Whisper</a> 一类大模型 ASR 的强项），但切换点附近的块边界处理仍归服务管。最后，录音与识别产物的留存是合规敏感项，ASR 的 final 文本属于对话记录，缓存与训练使用要单独授权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>级联对话延迟是四段相加：端点、识别、生成、合成，按段立 SLA 分账监控。</li><li>partial 上屏压缩体感延迟，final 才进 LLM；两层语义必须分开暴露。</li><li>TTS 按句切分加流式 vocoder，首音频从「整段完成」提前到「首句完成」。</li><li>打断四步（停播、弃队、作废、回听）要原子完成，漏一步就答非所问。</li><li>识别错误沿级联放大成「幻觉」，三跳中间产物必须落盘可归因。</li><li>出处：据 Whisper（Radford et al., 2023）、VALL-E（Wang et al., 2023）、Qwen3-ASR Technical Report 与语音对话系统文献整理。</li></ul>',6))])}const c=i(D,[["render",T]]);export{L as __pageData,c as default};
